import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:media_store_plus/media_store_plus.dart';
import 'package:path_provider/path_provider.dart';
import 'package:permission_handler/permission_handler.dart';

final mediaStorePlugin = MediaStore();
const String kAppFolder = "MediaStoreDemo";

// Demo base64 image provided
const String base64path =
    "";
void main() {
  runApp(const MediaStoreDemoApp());
}

class MediaStoreDemoApp extends StatelessWidget {
  const MediaStoreDemoApp({super.key});

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      title: 'Media Store Plus Demo',
      debugShowCheckedModeBanner: false,
      home: SaveImageDemoScreen(),
    );
  }
}

class SaveImageDemoScreen extends StatefulWidget {
  const SaveImageDemoScreen({super.key});

  @override
  State<SaveImageDemoScreen> createState() => _SaveImageDemoScreenState();
}

class _SaveImageDemoScreenState extends State<SaveImageDemoScreen> {
  bool _isSaving = false;

  Future<void> _saveImage() async {
    setState(() => _isSaving = true);

    try {
      // Initialize MediaStore when needed
      if (Platform.isAndroid) {
        await MediaStore.ensureInitialized();
      }
      MediaStore.appFolder = kAppFolder;

      // 1. Request required storage permissions
      if (Platform.isAndroid) {
        final sdk = await mediaStorePlugin.getPlatformSDKInt();
        if (sdk >= 33) {
          await Permission.photos.request();
        } else {
          // Android 10 (API 29) uses storage permission
          await Permission.storage.request();
        }
      }

      // 2. Decode base64 image and write to a temporary file
      final bytes = base64Decode(base64path);
      final tempDir = await getTemporaryDirectory();
      const fileName = "demo_base64_image.png";
      final tempFile = File("${tempDir.path}/$fileName");
      await tempFile.writeAsBytes(bytes);

      // 3. Save to MediaStore (Pictures/MediaStoreDemo)
      final saveInfo = await mediaStorePlugin.saveFile(
        tempFilePath: tempFile.path,
        dirType: DirType.download,
        dirName: DirType.download.defaults,
        relativePath: kAppFolder,
      );

      final isSuccess = saveInfo?.uri != null;
      final message = isSuccess
          ? "File saved successfully to ${saveInfo!.uri}"
          : "Failed to save file to device storage.";

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(message),
            backgroundColor: isSuccess ? Colors.green.shade700 : Colors.red.shade700,
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Error: $e"),
            backgroundColor: Colors.red.shade700,
          ),
        );
      }
    } finally {
      if (mounted) {
        setState(() => _isSaving = false);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Save File Demo'), centerTitle: true),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 24.0),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Text(
                'Click the button below to save the demo base64 image to device storage via MediaStore Plus.',
                textAlign: TextAlign.center,
                style: TextStyle(fontSize: 16),
              ),
              const SizedBox(height: 28),
              ElevatedButton.icon(
                onPressed: _isSaving ? null : _saveImage,
                icon: _isSaving
                    ? const SizedBox(
                        width: 18,
                        height: 18,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Icon(Icons.save_alt),
                label: Text(_isSaving ? 'Saving...' : 'Save Image'),
                style: ElevatedButton.styleFrom(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 28,
                    vertical: 14,
                  ),
                  textStyle: const TextStyle(fontSize: 16),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
